import net from 'node:net'

// A local SMTP inbox for runtime tests. Codes are generated by the application
// and delivered over the real nodemailer/Workers socket path, never fabricated.
export async function startSmokeSmtp() {
  const messages = [], sockets = new Set()
  const server = net.createServer((socket) => {
    sockets.add(socket)
    socket.on('close', () => sockets.delete(socket))
    socket.on('error', () => {})
    socket.write('220 localhost RentEase test SMTP\r\n')
    let buffer = '', data = false, recipient = '', content = []
    socket.on('data', (chunk) => {
      buffer += chunk.toString()
      let end
      while ((end = buffer.indexOf('\r\n')) !== -1) {
        const line = buffer.slice(0, end); buffer = buffer.slice(end + 2)
        if (data) {
          if (line !== '.') { content.push(line); continue }
          const message = content.join('\r\n'), body = message.split('\r\n\r\n').slice(1).join('\r\n\r\n')
          messages.push({ recipient, otp: body.match(/\b\d{6}\b/)?.[0], message })
          data = false; content = []; socket.write('250 accepted\r\n'); continue
        }
        if (/^EHLO|^HELO/i.test(line)) socket.write('250 localhost\r\n')
        else if (/^RCPT TO:/i.test(line)) { recipient = line.match(/<([^>]+)>/)?.[1] || ''; socket.write('250 recipient OK\r\n') }
        else if (/^DATA$/i.test(line)) { data = true; socket.write('354 end with dot\r\n') }
        else if (/^QUIT$/i.test(line)) socket.end('221 bye\r\n')
        else socket.write('250 OK\r\n')
      }
    })
  })
  await new Promise((resolve, reject) => { server.once('error', reject); server.listen(0, '127.0.0.1', resolve) })
  return {
    port: server.address().port,
    async next(email, after = 0) {
      for (let attempt = 0; attempt < 100; attempt += 1) {
        const found = messages.slice(after).find((message) => message.recipient === email)
        if (found?.otp) return found
        await new Promise((resolve) => setTimeout(resolve, 100))
      }
      throw new Error('The local SMTP inbox did not receive the verification email.')
    },
    get count() { return messages.length },
    async close() {
      for (const socket of sockets) socket.destroy()
      await new Promise((resolve) => server.close(resolve))
    },
  }
}
